import React from 'react';
import { Routes, Route, Link } from 'react-router-dom';
import { HiOutlineUser, HiOutlineCreditCard } from 'react-icons/hi';

// Simple home component
const Home = () => (
  <div className="p-8 text-center">
    <h1 className="text-4xl font-bold text-primestone-900 mb-4">PrimeStone Investment</h1>
    <p className="text-xl text-primestone-600 mb-8">Secure • Transparent • Profitable</p>
    <div className="space-x-4">
      <Link to="/login" className="bg-primestone-600 text-white px-6 py-3 rounded-lg">Login</Link>
      <Link to="/register" className="border-2 border-primestone-600 text-primestone-600 px-6 py-3 rounded-lg">Register</Link>
    </div>
  </div>
);

// Simple placeholder components
const Login = () => <div className="p-8 text-center text-2xl">Login Page</div>;
const Register = () => <div className="p-8 text-center text-2xl">Register Page</div>;
const Dashboard = () => <div className="p-8 text-center text-2xl">Dashboard Page</div>;

function App() {
  return (
    <div className="min-h-screen bg-gradient-to-b from-primestone-50 to-white">
      {/* Simple Navigation */}
      <nav className="bg-primestone-600 p-4">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <Link to="/" className="text-white font-bold text-xl">PrimeStone</Link>
          <div className="space-x-4">
            <Link to="/login" className="text-white hover:text-primestone-200">Login</Link>
            <Link to="/register" className="text-white hover:text-primestone-200">Register</Link>
            <Link to="/dashboard" className="text-white hover:text-primestone-200">Dashboard</Link>
          </div>
        </div>
      </nav>

      {/* Routes */}
      <div className="max-w-7xl mx-auto p-4">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/dashboard" element={<Dashboard />} />
        </Routes>
      </div>
    </div>
  );
}

export default App;
